let controller=null;
const time=seconds=>{const value=Number.isFinite(seconds)?Math.max(0,Math.floor(seconds)):0;return Math.floor(value/60)+':'+String(value%60).padStart(2,'0');};
export function initFloatingAudio({doc=document,win=window,scope=()=>'',origin=()=>win.location.origin,refreshAccess,onPlay,toast}={}){
 if(controller)return controller;
 // The media element stays in the document body. Only its controls move into
 // full-page readers, so changing a page or dialog never interrupts playback.
 const media=doc.createElement('audio');media.id='richmountFloatingMedia';media.hidden=true;media.preload='metadata';media.setAttribute('aria-hidden','true');media.setAttribute('controlslist','nodownload');
 const panel=doc.createElement('section');panel.id='richmountFloatingPlayer';panel.className='floating-player';panel.hidden=true;panel.setAttribute('role','region');panel.setAttribute('aria-labelledby','floatingAudioTitle');
 panel.innerHTML='<div class="floating-player-header"><div><span class="floating-player-label">RICHMOUNT · AUDIO</span><strong id="floatingAudioTitle">Your recording</strong></div><button type="button" class="floating-icon-button" data-floating-action="play" aria-label="Play audio">▶</button><button type="button" class="floating-icon-button" data-floating-action="minimize" aria-label="Minimize audio player" aria-expanded="true" aria-controls="floatingAudioControls">⌄</button><button type="button" class="floating-icon-button" data-floating-action="close" aria-label="Close audio player and stop playback">×</button></div><div id="floatingAudioControls"><label class="sr-only" for="floatingAudioSeek">Position in the recording</label><input type="range" id="floatingAudioSeek" min="0" max="0" step="1" value="0" disabled><div class="floating-player-time"><span id="floatingAudioTime">0:00 / 0:00</span><span id="floatingAudioStatus" role="status" aria-live="polite">Ready to play</span></div><div class="floating-player-actions"><button type="button" data-floating-action="back" aria-label="Go back 10 seconds">↶ 10s</button><button type="button" data-floating-action="replay">↻ Replay</button><button type="button" data-floating-action="forward" aria-label="Go forward 10 seconds">10s ↷</button></div></div>';
 doc.body.append(media);doc.body.append(panel);
 const title=panel.querySelector('#floatingAudioTitle'),seek=panel.querySelector('#floatingAudioSeek'),clock=panel.querySelector('#floatingAudioTime'),status=panel.querySelector('#floatingAudioStatus'),play=panel.querySelector('[data-floating-action="play"]'),minimize=panel.querySelector('[data-floating-action="minimize"]'),controls=panel.querySelector('#floatingAudioControls');
 let item=null,generation=0,refreshing=false,pendingSeek=null,message='',minimized=false,returnFocus=null,wantedPlaying=false,lastRenewal=0;
 const owner=()=>String(scope()||'guest');
 function place(){let dialog=null;try{dialog=doc.querySelector('dialog:modal');}catch{dialog=doc.querySelector('.materials-reader[data-material-reader-view="page"][open]');}const parent=dialog||doc.body;if(panel.parentNode!==parent)parent.append(panel);}
 function home(){if(panel.parentNode!==doc.body)doc.body.append(panel);}
 function paint(){if(!item)return;const duration=Number.isFinite(media.duration)?media.duration:0,position=media.currentTime||0;title.textContent=item.title||'Audio recording';play.textContent=media.paused?'▶':'Ⅱ';play.setAttribute('aria-label',media.paused?'Play audio':'Pause audio');seek.max=String(Math.floor(duration));seek.value=String(Math.floor(position));seek.disabled=!duration;seek.setAttribute('aria-valuetext',time(position)+' of '+time(duration));clock.textContent=time(position)+' / '+time(duration);status.textContent=message||(media.ended?'Finished · Replay when you’re ready':media.paused?'Paused':'Playing');controls.hidden=minimized;minimize.textContent=minimized?'⌃':'⌄';minimize.setAttribute('aria-expanded',String(!minimized));minimize.setAttribute('aria-label',minimized?'Expand audio player':'Minimize audio player');panel.classList.toggle('is-minimized',minimized);doc.body.classList.toggle('has-floating-audio-minimized',minimized);place();}
 function close(focus=false){generation++;item=null;refreshing=false;pendingSeek=null;message='';wantedPlaying=false;lastRenewal=0;media.pause();media.removeAttribute('src');media.load();home();panel.hidden=true;title.textContent='Your recording';status.textContent='';doc.body.classList.remove('has-floating-audio');doc.body.classList.remove('has-floating-audio-minimized');if(focus){const target=returnFocus?.isConnected?returnFocus:doc.querySelector('#app');target?.focus?.({preventScroll:true});}returnFocus=null;}
 function sync(){if(item&&item.owner!==owner())close();}
 function sourceKey(src){const url=new URL(src,win.location.origin),allowed=['https:','http:','blob:'].includes(url.protocol),trusted=url.protocol==='blob:'?url.origin===win.location.origin:[win.location.origin,origin()].includes(url.origin)&&/^\/api\/(materials|audio)\/file\//.test(url.pathname);if(!allowed||!trusted)throw new Error('This recording cannot be played here.');return url.protocol==='blob:'?src:url.origin+url.pathname;}
 async function start(){sync();if(!item)return;const original=item,version=generation;message='';wantedPlaying=true;try{await media.play();}catch{if(version!==generation||item!==original)return;wantedPlaying=false;message='Press Play to start the recording.';}if(version===generation&&item===original)paint();}
 function open(value){sync();if(!value?.url)return false;const generatedKey=sourceKey(value.url),key=value.key||generatedKey,expected=String(value.owner||owner());if(expected!==owner())return false;
  if(item&&item.key===key&&item.owner===expected){if(value.title)item.title=value.title;panel.hidden=false;if(value.autoplay)void start();paint();return true;}
  close();item={url:value.url,key,owner:expected,title:value.title||'Audio recording'};returnFocus=value.originElement||null;pendingSeek=Number.isFinite(value.startAt)?value.startAt:0;panel.hidden=false;doc.body.classList.add('has-floating-audio');media.src=value.url;media.load();paint();if(value.autoplay)void start();return true;
 }
 function pause(){wantedPlaying=false;if(item){media.pause();paint();}}
 function seekTo(value){if(!item||!Number.isFinite(value))return;const maximum=Number.isFinite(media.duration)?media.duration:Math.max(0,value),position=Math.max(0,Math.min(maximum,value));try{media.currentTime=position;}catch{pendingSeek=position;}paint();}
 async function renew(){sync();if(!item||refreshing)return;if(Date.now()-lastRenewal<5000){message='Open this recording again to refresh its access.';media.pause();paint();return;}lastRenewal=Date.now();const original=item,version=generation,position=media.currentTime||0,wasPlaying=wantedPlaying;message='Reconnecting audio…';refreshing=true;paint();try{if(!refreshAccess||original.url.startsWith('blob:'))throw new Error('Open this recording again from its lesson or speaking page.');const access=await refreshAccess(original.url);if(version!==generation||item!==original||original.owner!==owner())return;sourceKey(access.url);item.url=access.url;pendingSeek=position;media.src=access.url;media.load();message='';if(wasPlaying&&wantedPlaying)await start();}catch(error){if(version===generation&&item===original){message=error.message||'Open this recording again to refresh its access.';media.pause();}}finally{if(version===generation){refreshing=false;paint();}}}
 function adopt(inline){if(inline===media||inline.tagName!=='AUDIO'||!inline.closest('#app'))return;const src=inline.currentSrc||inline.src;if(!src)return;try{sourceKey(src);}catch(error){inline.pause();toast?.(error.message);return;}const inlineOwner=inline.dataset.floatingOwner||owner();if(inlineOwner!==owner()){inline.pause();return;}
  const label=inline.getAttribute('aria-label')||inline.closest('article')?.querySelector('strong')?.textContent||'Your speaking recording';const position=inline.currentTime||0;inline.pause();inline.hidden=true;const opened=open({url:src,title:label,owner:inlineOwner,startAt:position,autoplay:true,originElement:inline});
  if(opened&&!inline.dataset.floatingTransferred){inline.dataset.floatingTransferred='true';const button=doc.createElement('button');button.type='button';button.className='button secondary floating-return-button';button.textContent='Open floating audio player';button.addEventListener('click',()=>{if(open({url:src,title:label,owner:inlineOwner,originElement:button})){minimized=false;paint();play.focus();}});inline.insertAdjacentElement('afterend',button);}
 }
 panel.addEventListener('click',event=>{const action=event.target.closest('[data-floating-action]')?.dataset.floatingAction;if(!action)return;if(action==='close'){close(true);return;}if(action==='play'){if(media.paused)void start();else pause();}if(action==='minimize'){minimized=!minimized;paint();}if(action==='replay'){seekTo(0);void start();}if(action==='back')seekTo((media.currentTime||0)-10);if(action==='forward')seekTo((media.currentTime||0)+10);});
 seek.addEventListener('input',()=>seekTo(Number(seek.value)));
 for(const event of ['pause','timeupdate','durationchange','ended','waiting','playing'])media.addEventListener(event,()=>{if(event==='waiting')message='Buffering…';if(event==='playing')message='';paint();});
 media.addEventListener('loadedmetadata',()=>{if(pendingSeek!==null){seekTo(pendingSeek);pendingSeek=null;}paint();});media.addEventListener('play',()=>{if(item?.owner!==owner()){close();return;}doc.querySelectorAll('#app audio,#app video').forEach(other=>other.pause());onPlay?.();paint();});media.addEventListener('error',()=>{if(item)void renew();});
 doc.addEventListener('play',event=>{if(event.target===media)return;if(event.target.tagName==='AUDIO')adopt(event.target);else if(event.target.tagName==='VIDEO')pause();},true);
 doc.addEventListener('close',event=>{if(event.target.contains?.(panel)&&!event.target.open){home();place();}},true);
 panel.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);}});
 function viewport(){const visible=win.visualViewport,offset=visible?Math.max(0,(win.innerHeight||0)-visible.height-visible.offsetTop):0;panel.style.setProperty('--audio-keyboard-offset',Math.round(offset)+'px');}win.addEventListener('resize',viewport);win.visualViewport?.addEventListener('resize',viewport);win.visualViewport?.addEventListener('scroll',viewport);viewport();
 controller={open,close,pause,sync,home,actor:owner,reposition:place,state:()=>({key:item?.key||'',owner:item?.owner||'',url:item?.url||'',playing:!!item&&!media.paused,currentTime:media.currentTime||0,visible:!panel.hidden}),closeSource:src=>{if(item&&(item.url===src||item.key===src||src?.startsWith('/')&&new URL(item.url).pathname===src))close();},media,panel};return controller;
}
export const openFloatingAudio=value=>controller?.open(value)||false;
export const moveFloatingAudioHome=()=>controller?.home();
export const placeFloatingAudio=()=>controller?.reposition();
export const syncFloatingAudioOwner=()=>controller?.sync();
export const closeFloatingAudio=()=>controller?.close();
export const closeFloatingAudioSource=src=>controller?.closeSource(src);
export const pauseFloatingAudio=()=>controller?.pause();
export const floatingAudioOwner=()=>controller?.actor()||'';
